insert into public.venues (id, name, kind, quartier_id, address, status, verification, data_origin, opening_hours, admission, free_when, visit_tips, info_checked_on) values ('586bce06-dd32-5da6-8a4b-e1f59a946b96', 'Kunsthaus Zürich', 'Museum', (select q.id from public.quartiers q join public.districts d on d.id = q.district_id where d.city_id = 'zurich' and q.name = 'Hochschulen'), 'Heimplatz 1, 8001 Zürich', 'published', 'provider_verified', 'provider:site', 'Di–Mi und Fr–So 10–18 Uhr · Do 10–20 Uhr · Montag geschlossen. Geschlossen am 25.12.2026 und 1.1.2027.', 'Kinder und Jugendliche unter 14 Jahren: gratis. Erwachsene: Sammlung CHF 24 (ermässigt 17), grosse Ausstellung CHF 31 (ermässigt 22).', 'Mittwochs ist der Eintritt in die Sammlung für alle kostenlos (Ausstellungen kosten extra).', 'Kinderwagen sind erlaubt (mit Auflagen). Essen und Trinken, auch Babynahrung und Milchflaschen, nur im Café beim Eingang. Der Kinder-Audioguide ist kostenlos. Die Kinderworkshops am Mittwoch sind für Kinder ab 6 Jahren.', '2026-11-18') on conflict (id) do update set opening_hours = excluded.opening_hours, admission = excluded.admission, free_when = excluded.free_when, visit_tips = excluded.visit_tips, info_checked_on = excluded.info_checked_on;
