insert into public.venues (id, name, kind, quartier_id, address, status, verification, data_origin, opening_hours, admission, free_when, visit_tips, info_checked_on) values ('f587f3e3-cdf5-5112-beb4-cbfc4e43a04b', 'Landesmuseum Zürich', 'Museum', (select q.id from public.quartiers q join public.districts d on d.id = q.district_id where d.city_id = 'zurich' and q.name = 'City'), 'Museumstrasse 2, 8001 Zürich', 'published', 'provider_verified', 'provider:site', 'Di–So 10–17 Uhr · Montag geschlossen. 24.12.2026 bis 14 Uhr. Geschlossen am 19.4.2027 (Sechseläuten) und 13.9.2027 (Knabenschiessen).', 'Kinder und Jugendliche bis 16 Jahre: Eintritt frei. Erwachsene: Preise auf landesmuseum.ch/tickets.', 'Kinder und Jugendliche bis 16 Jahre haben immer freien Eintritt.', 'Familienausstellung mit drei Themenräumen (Orient, Schifffahrt, Eisenbahn). Mittwoch- und Samstagnachmittag: interaktiv erzählte Geschichte auf Sitzkissen. Mit dem Entdeckungskoffer können Kinder das Museum auf eigene Faust erkunden. Hinweise zum Kinderwagen: auf der Website unter «Mit dem Kinderwagen ins Museum».', '2026-11-18') on conflict (id) do update set opening_hours = excluded.opening_hours, admission = excluded.admission, free_when = excluded.free_when, visit_tips = excluded.visit_tips, info_checked_on = excluded.info_checked_on;
