insert into public.venues (id, name, kind, quartier_id, address, status, verification, data_origin, opening_hours, admission, free_when, visit_tips, info_checked_on) values ('00f7eb89-0b1a-579d-81c0-88ebf7cfcd29', 'Mühlerama', 'Museum', (select q.id from public.quartiers q join public.districts d on d.id = q.district_id where d.city_id = 'zurich' and q.name = 'Mühlebach'), 'Seefeldstrasse 231, 8008 Zürich', 'published', 'provider_verified', 'provider:site', 'Di, Do, Fr, Sa 14–18 Uhr · Mi 14–21 Uhr · So 10–17 Uhr. Backwerkstatt: Di–Sa 14–16.30 Uhr, So und Feiertage 10–15.30 Uhr. Geschlossen am 24., 25., 26. und 31.12.2026 und am 1.1.2027.', 'Erwachsene CHF 15 · Kinder und Jugendliche 6–18 Jahre CHF 9 · Kinder 2–5 Jahre CHF 5 (Preise ab 1.1.2025). Ein Preis für Kinder unter 2 Jahren ist auf der Website nicht aufgeführt.', 'Freier Eintritt mit ZürichCARD, Kulturlegi, Schweizerischem Museumspass und Raiffeisen Member Plus Karte.', 'Kinder unter 16 Jahren nur mit erwachsener Begleitung. In der Backwerkstatt kann es zu Wartezeiten kommen: das Museum empfiehlt, den Besuch am Empfang zu planen. Mittwochs bis 21 Uhr geöffnet.', '2026-11-18') on conflict (id) do update set opening_hours = excluded.opening_hours, admission = excluded.admission, free_when = excluded.free_when, visit_tips = excluded.visit_tips, info_checked_on = excluded.info_checked_on;
